scripts.onStarted:
/**
 * window.strut — PathwAI Finasteride Oral Tablets event file / checkout SDK.
 *
 * Paste this entire file into the Finasteride Oral Tablets PathwAI flow only.
 * Do not paste into BHRT, SuperStrut, Semaglutide, Sildenafil, Tadalafil,
 * Tirzepatide, Dutasteride, Enclomiphene, or the topical Finasteride hair loss flow.
 *
 * Staging (checkout.strut-test.com/finasteride-oral-tablets):
 *   s1  → 48  ($25 / 30 Day Supply - 1mg)
 *   s2  → 49  ($49 / 90 Day Supply - 1mg)
 * Production (checkout.struthealth.com/finasteride-oral-tablets):
 *   s1  → 48  ($25 / 30 Day Supply - 1mg)
 *   s2  → 49  ($49 / 90 Day Supply - 1mg)
 *
 * FinishOrderV2 always sends productPriceId so checkout does not fall
 * back to a leftover SKU from another flow.
 *
 * Paste pathwai-finasteride-oral-tablets-pricing-card.tsx into the Add to cart / product card.
 * That card calls strut.addToCart() → validateVisiting → pathwai.flow.next().
 *
 *   await strut.status()
 *   await strut.validateVisiting('finasteride-oral-tablets', strut.skuId('s1'))
 *   await strut.validateVisiting('finasteride-oral-tablets', strut.skuId('s2'))
 *   await strut.finishOrderV2({ customerProfileId, paymentProfileId })
 *
 * A selfie or ID photo is uploaded with PUT media/UploadFiles, then attached
 * with POST checkout/SavePhotoUpload before FinishOrderV2. Admin and physician
 * Photos read those PhotoUpload rows after the order succeeds.
 */
//window.strut_env = 'staging';
(function () {
  'use strict';

  function detectEnv() {
    const isStaging = window.strut_env === 'staging';
    if (isStaging) {
      return {
        api: 'https://checkout-api.strut-test.com/api',
        checkout: 'https://checkout.strut-test.com',
        account: 'https://my.strut-test.com',
        namespace: 'struthealthProd',
      };
    }
    return {
      api: 'https://checkout-api.struthealth.com/api',
      checkout: 'https://checkout.struthealth.com',
      account: 'https://my.struthealth.com',
      namespace: 'struthealthGoLive',
    };
  }

  const ENV = detectEnv();
  const LS = {
    ACCESS_TOKEN:   `${ENV.namespace}_AccessToken`,
    VISITING:       'Visiting',
    VISITING_ORDER: 'Visiting.OrderId',
    AUTH_PARAMS:    'AuthParams',
    LINK_CHECKOUT:  'LinkCheckout',
    QUESTIONS:      'QuestionAnswers',
    SELECTED_PRICE: 'Strut.FinasterideOralTabletsPriceId',
    AUTHNET:        'Strut.FinasterideOralTabletsAuthNet',
    FINISH_LOCK:    'Strut.FinasterideOralTabletsOrderSubmitted',
    PHOTOS:         'Strut.FinasterideOralTabletsPhotos',
    PHOTOS_SAVED:   'Strut.FinasterideOralTabletsPhotosSaved',
  };

  // PathwAI SKU map. Prod ids are invalid on staging and vice versa.
  const FINASTERIDE_ORAL_TABLETS = [
    { key: 's1', staging: 48, prod: 48, amount: 25, days: 30, label: '30 Day Supply - 1mg' },
    { key: 's2', staging: 49, prod: 49, amount: 49, days: 90, label: '90 Day Supply - 1mg' },
  ];

  function lsGet(key) {
    const raw = localStorage.getItem(key);
    if (!raw || raw === 'undefined') return null;
    try { return JSON.parse(raw); } catch { return null; }
  }
  function lsSet(key, value) { localStorage.setItem(key, JSON.stringify(value)); }
  function lsDel(key) { localStorage.removeItem(key); }

  function isJwtExpired(token) {
    if (!token) return true;
    try {
      const payload = JSON.parse(atob(token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')));
      return typeof payload.exp === 'number' && Date.now() / 1000 >= payload.exp;
    } catch (e) {
      return true;
    }
  }

  function getToken() {
    const user = lsGet(LS.ACCESS_TOKEN);
    const token = user?.AccessToken?.Token || null;
    if (!token) return null;
    if (isJwtExpired(token)) {
      _log('Ignoring expired AccessToken');
      return null;
    }
    return token;
  }

  function setTokenFromBearer(bearerString) {
    const token = bearerString.replace(/^Bearer\s+/i, '').trim();
    const existing = lsGet(LS.ACCESS_TOKEN) || {};
    if (!existing.AccessToken) existing.AccessToken = {};
    existing.AccessToken.Token = token;
    lsSet(LS.ACCESS_TOKEN, existing);
    _log('Token stored under', LS.ACCESS_TOKEN);
    return token;
  }

  function isCheckoutApiUrl(url) {
    return /checkout-api\.strut(-test)?\.com/i.test(String(url || ''));
  }

  /** PathwAI Persona / GetCurrentVisiting often omit Authorization — inject Strut JWT. */
  function withAuthHeaders(headers, token) {
    if (!token) return headers;
    const next = headers || {};
    if (typeof Headers !== 'undefined' && next instanceof Headers) {
      if (!next.has('Authorization')) next.set('Authorization', `Bearer ${token}`);
      return next;
    }
    const plain = { ...(typeof next === 'object' ? next : {}) };
    const hasAuth = Object.keys(plain).some(k => k.toLowerCase() === 'authorization');
    if (!hasAuth) plain.Authorization = `Bearer ${token}`;
    return plain;
  }

  function base() { return ENV.api.replace(/\/$/, ''); }

  function jsonHeaders(token) {
    const h = { 'Accept': 'application/json', 'Content-Type': 'application/json' };
    if (token) h['Authorization'] = `Bearer ${token}`;
    return h;
  }

  function formHeaders(token) {
    const h = { 'Accept': 'application/json', 'Content-Type': 'application/x-www-form-urlencoded' };
    if (token) h['Authorization'] = `Bearer ${token}`;
    return h;
  }

  function toForm(obj) {
    return Object.entries(obj)
      .filter(([, v]) => v !== undefined && v !== null)
      .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
      .join('&');
  }

  async function api(method, path, opts = {}) {
    const token = opts.token || getToken();
    const url   = `${base()}/${path.replace(/^\//, '')}`;
    const init  = { method };

    if (opts.formData !== undefined) {
      init.headers = { Accept: 'application/json' };
      if (token) init.headers.Authorization = `Bearer ${token}`;
      init.body = opts.formData;
    } else if (opts.json !== undefined) {
      init.headers = jsonHeaders(token);
      init.body    = JSON.stringify(opts.json);
    } else if (opts.form !== undefined) {
      init.headers = formHeaders(token);
      init.body    = toForm(opts.form);
    } else if (opts.empty) {
      init.headers = { ...jsonHeaders(token), 'Content-Length': '0' };
    } else {
      init.headers = jsonHeaders(token);
    }

    const res  = await fetch(url, init);
    const text = await res.text();
    let data;
    try { data = text ? JSON.parse(text) : null; } catch { data = text; }

    if (!res.ok) {
      const err     = new Error(`${method} ${path} → ${res.status}`);
      err.status    = res.status;
      err.body      = data;
      err.url       = url;
      console.error('[strut]', err.message, data);
      throw err;
    }
    return data;
  }

  function _log(label, ...args) {
    console.log(`%c[strut] ${label}`, 'color:#6c47ff;font-weight:bold', ...args);
  }

  function getVisiting()      { return lsGet(LS.VISITING); }
  function getOrder()         { return lsGet(LS.VISITING_ORDER); }
  function getAuthParams()    { return lsGet(LS.AUTH_PARAMS); }
  function getAccessUser()    { return lsGet(LS.ACCESS_TOKEN); }
  function getVisitingId()    { return getVisiting()?.VisitingId; }
  function getOrderId()       { return getOrder()?.OrderId; }
  function getProductPriceId(){ return getOrder()?.Cart?.ProductPriceId; }

  function isProdApi() {
    return /checkout-api\.struthealth\.com/i.test(ENV.api) || window.strut_env === 'production';
  }

  function finasterideOralTabletsId(key) {
    const row = FINASTERIDE_ORAL_TABLETS.find(s => s.key === key);
    if (!row) return 0;
    if (isProdApi()) return Number(row.prod) || Number(row.staging) || 0;
    return Number(row.staging) || 0;
  }

  function isFinasterideOralTabletsPriceId(id) {
    const n = Number(id);
    return FINASTERIDE_ORAL_TABLETS.some(s => s.staging === n || (s.prod && s.prod === n));
  }

  function skuRowById(id) {
    const n = Number(id);
    return FINASTERIDE_ORAL_TABLETS.find(s => s.staging === n || (s.prod && s.prod === n)) || null;
  }

  const THIS_SLUG = 'finasteride-oral-tablets';
  const SLUG_ALIASES = [THIS_SLUG, 'finasteride_oral_tablets', 'finasteride oral tablets'];

  function normalizeSlug(slug) {
    return String(slug || '').trim().toLowerCase();
  }

  function isThisSlug(slug) {
    const s = normalizeSlug(slug);
    return !s || SLUG_ALIASES.includes(s);
  }

  function priceBelongsToThisFlow(id) {
    const n = Number(id);
    if (!n) return true;
    return isFinasterideOralTabletsPriceId(n);
  }

  function resetCheckoutSession(reason) {
    const prev = getVisiting();
    lsDel(LS.VISITING);
    lsDel(LS.VISITING_ORDER);
    lsDel(LS.LINK_CHECKOUT);
    lsDel(LS.QUESTIONS);
    lsDel(LS.SELECTED_PRICE);
    lsDel(LS.AUTHNET);
    lsDel(LS.PHOTOS);
    lsDel(LS.PHOTOS_SAVED);
    try { delete window.strut_finasteride_oral_tablets_price_id; } catch (e) { /* ignore */ }
    try { delete window.strut_authnet_profiles; } catch (e) { /* ignore */ }
    try { sessionStorage.removeItem(LS.FINISH_LOCK); } catch (e) { /* ignore */ }
    _log('Reset checkout session (login kept)', reason, prev);
  }

  function visitingMatchesIncoming(slug, priceId) {
    const stored = getVisiting();
    if (!stored) return false;
    const nextSlug = normalizeSlug(slug || THIS_SLUG) || THIS_SLUG;
    const storedSlug = normalizeSlug(stored.ProductSlug);
    const nextPrice = Number(priceId || 0);
    const storedPrice = Number(stored.ProductPriceId || 0);
    if (storedSlug && !isThisSlug(storedSlug)) return false;
    if (!priceBelongsToThisFlow(storedPrice)) return false;
    if (storedSlug && nextSlug && isThisSlug(storedSlug) !== isThisSlug(nextSlug)) return false;
    if (nextPrice && storedPrice && remapFinasterideOralTabletsId(nextPrice) !== remapFinasterideOralTabletsId(storedPrice)) return false;
    return true;
  }

  function discardStaleSessionForIncoming(slug, priceId) {
    if (visitingMatchesIncoming(slug, priceId)) return false;
    resetCheckoutSession({ slug: slug || THIS_SLUG, priceId: Number(priceId || 0) });
    return true;
  }

  function discardForeignSessionOnLoad() {
    const stored = getVisiting();
    if (!stored) return;
    const slug = normalizeSlug(stored.ProductSlug);
    const price = Number(stored.ProductPriceId || 0);
    if ((slug && !isThisSlug(slug)) || !priceBelongsToThisFlow(price)) {
      resetCheckoutSession({ onLoad: true, slug, price });
    }
  }

  const FLOW_LOCK = 'Strut.PathwaiFlowLock';

  function readPathwaiSubmissionId() {
    try {
      if (typeof submissionId !== 'undefined' && submissionId) return String(submissionId);
    } catch (e) { /* not in this event */ }
    try {
      if (window.pathwai && window.pathwai.submissionId) return String(window.pathwai.submissionId);
    } catch (e) { /* ignore */ }
    return '';
  }

  function beginCheckoutFlow() {
    const stored = getVisiting();
    const storedSlug = stored ? normalizeSlug(stored.ProductSlug) : '';
    const sub = readPathwaiSubmissionId();
    let prevLock = '';
    try { prevLock = sessionStorage.getItem(FLOW_LOCK) || ''; } catch (e) { /* ignore */ }

    const foreign = !!(stored && storedSlug && !isThisSlug(storedSlug));
    const lock = THIS_SLUG + '|' + (sub || '');
    const continuing =
      !foreign &&
      isThisSlug(storedSlug) && storedSlug &&
      prevLock.indexOf(THIS_SLUG + '|') === 0 &&
      (!sub || prevLock === lock || prevLock === THIS_SLUG + '|');

    if (!continuing && isThankYouScreen()) {
      _log('Thank-you step — keeping visiting so FinishOrder can run');
    } else if (!continuing) {
      resetCheckoutSession({ reason: 'flow-start', foreign: foreign, lock: lock, prevLock: prevLock, sub: sub });
    } else {
      discardForeignSessionOnLoad();
    }
    try {
      sessionStorage.setItem(
        FLOW_LOCK,
        sub ? lock : (prevLock.indexOf(THIS_SLUG + '|') === 0 ? prevLock : lock)
      );
    } catch (e) { /* ignore */ }
  }

  function remapFinasterideOralTabletsId(id) {
    const n = Number(id);
    if (!n) return 0;
    const row = FINASTERIDE_ORAL_TABLETS.find(s => s.staging === n || (s.prod && s.prod === n));
    if (!row) return n;
    if (isProdApi()) return Number(row.prod) || Number(row.staging) || 0;
    return Number(row.staging) || 0;
  }

  function rememberSku(id) {
    const mapped = remapFinasterideOralTabletsId(id);
    if (!isFinasterideOralTabletsPriceId(mapped)) return 0;
    lsSet(LS.SELECTED_PRICE, mapped);
    try { window.strut_finasteride_oral_tablets_price_id = mapped; } catch (e) { /* ignore */ }
    return mapped;
  }

  function rememberedSku() {
    return remapFinasterideOralTabletsId(Number(lsGet(LS.SELECTED_PRICE) || window.strut_finasteride_oral_tablets_price_id || 0));
  }

  /** Resolve priceId from 's1' | 's2' | '30' | '90' | full label. */
  function skuId(sizeOrKey) {
    const key = normalizeSkuKey(sizeOrKey);
    return key ? finasterideOralTabletsId(key) : 0;
  }
  const vialId = skuId;

  function readUrlPriceId() {
    try {
      const q = new URLSearchParams((window.location && window.location.search) || '');
      return Number(q.get('priceId') || q.get('productPriceId') || 0);
    } catch (e) {
      return 0;
    }
  }

  function normalizeSkuKey(raw) {
    const s = String(raw || '').trim().toLowerCase().replace(/\s+/g, ' ');
    if (!s) return '';
    const exact = FINASTERIDE_ORAL_TABLETS.find(p => p.key === s || p.label.toLowerCase() === s);
    if (exact) return exact.key;
    const compact = s.replace(/[\s|-]+/g, '_');
    const byKey = FINASTERIDE_ORAL_TABLETS.find(p => p.key === compact);
    if (byKey) return byKey.key;
    if (/^s1$/.test(compact) || /^30$/.test(compact)) return 's1';
    if (/^s2$/.test(compact) || /^90$/.test(compact)) return 's2';
    if (/48/.test(s) || /\$\s*25\b/.test(s)) return 's1';
    if (/49/.test(s) || /\$\s*49\b/.test(s)) return 's2';
    if (/\b90[\s-]?day\b/.test(s)) return 's2';
    if (/\b30[\s-]?day\b/.test(s)) return 's1';
    return '';
  }

  function skuFromUniquePrice(text) {
    const t = String(text || '');
    if (!t) return 0;
    const hits = FINASTERIDE_ORAL_TABLETS.filter(p => new RegExp('(?:\\$\\s*)' + p.amount + '(?:\\.00)?\\b').test(t));
    return hits.length === 1 ? finasterideOralTabletsId(hits[0].key) : 0;
  }

  function skuFromText(text) {
    const fromPrice = skuFromUniquePrice(text);
    if (fromPrice) return fromPrice;
    const key = normalizeSkuKey(text);
    return key ? finasterideOralTabletsId(key) : 0;
  }

  function readPathwaiValue(names) {
    const list = Array.isArray(names) ? names : [names];
    const bags = [];
    try {
      const q = new URLSearchParams((window.location && window.location.search) || '');
      const fromUrl = {};
      list.forEach(n => { fromUrl[n] = q.get(n); });
      bags.push(fromUrl);
    } catch (e) { /* ignore */ }
    try { bags.push(window.pathwai?.user?.answers); } catch (e) { /* ignore */ }
    try { bags.push(window.pathwai?.answers); } catch (e) { /* ignore */ }
    try { bags.push(window.pathwai?.user); } catch (e) { /* ignore */ }
    try { bags.push(lsGet(LS.QUESTIONS)); } catch (e) { /* ignore */ }
    for (const bag of bags) {
      if (!bag || typeof bag !== 'object') continue;
      for (const name of list) {
        const v = bag[name];
        if (v != null && v !== '') return v;
      }
    }
    for (const name of list) {
      try {
        const w = window[name];
        if (typeof w === 'string' || typeof w === 'number') return w;
      } catch (e) { /* ignore */ }
    }
    return '';
  }

  function skuFromPathwaiAnswers() {
    return skuFromText(
      readPathwaiValue([
        'sku', 'Sku', 'formula', 'Formula', 'form', 'Form',
        'dose', 'Dose', 'strength', 'Strength', 'product', 'Product', 'selection', 'Selection',
      ])
    );
  }

  function selectedNodesText() {
    if (!document || !document.querySelectorAll) return '';
    const nodes = document.querySelectorAll(
      '[aria-pressed="true"], [aria-checked="true"], [data-selected="true"], .is-selected, .selected, input:checked, [role="radio"][aria-checked="true"]'
    );
    const parts = [];
    nodes.forEach(n => {
      const card = n.closest('button, [role="button"], label, li, article') || n;
      parts.push((card.innerText || card.textContent || '').slice(0, 400));
    });
    return parts.join('\n');
  }

  function detectFinasterideOralTabletsFromSelectedDom() {
    return skuFromText(selectedNodesText());
  }

  // Do not scan the whole page — the PathwAI card lists every formula option.
  function cartSummaryText() {
    const t = (document && document.body && document.body.innerText) || '';
    if (!t) return '';
    const orderBlock = t.match(/your order[\s\S]{0,4000}?(?:subtotal|what happens next)/i);
    return orderBlock ? orderBlock[0] : '';
  }

  function detectFinasterideOralTabletsFromCart() {
    const text = cartSummaryText();
    if (!text || !/finasteride/i.test(text)) return 0;
    return skuFromText(text);
  }

  function visitingPriceId() {
    return Number(getVisiting()?.ProductPriceId || getOrder()?.Cart?.ProductPriceId || 0);
  }

  function resolvePrimaryPriceId(fallback) {
    const fromAnswers = skuFromPathwaiAnswers();
    if (fromAnswers) return rememberSku(fromAnswers);

    const fromDom = detectFinasterideOralTabletsFromSelectedDom();
    const fromArg = remapFinasterideOralTabletsId(Number(fallback || 0));
    const defaultStart = finasterideOralTabletsId('s1');
    // PathwAI JS may hardcode the first option. A different selected card wins.
    if (fromDom && fromArg === defaultStart && fromDom !== defaultStart) return rememberSku(fromDom);
    if (fromDom && !isFinasterideOralTabletsPriceId(fromArg)) return rememberSku(fromDom);
    if (isFinasterideOralTabletsPriceId(fromArg)) return rememberSku(fromArg);

    const fromExplicit = remapFinasterideOralTabletsId(Number(window.strut_finasteride_oral_tablets_price_id || 0));
    if (isFinasterideOralTabletsPriceId(fromExplicit)) return fromExplicit;

    const fromUrl = remapFinasterideOralTabletsId(readUrlPriceId());
    if (isFinasterideOralTabletsPriceId(fromUrl)) return rememberSku(fromUrl);

    const fromRemembered = rememberedSku();
    if (isFinasterideOralTabletsPriceId(fromRemembered)) return fromRemembered;

    const visit = remapFinasterideOralTabletsId(visitingPriceId());
    if (isFinasterideOralTabletsPriceId(visit)) return visit;

    const fromCart = detectFinasterideOralTabletsFromCart();
    if (fromCart) return rememberSku(fromCart);

    return fromArg || visit || 0;
  }

  function resolveCheckoutPriceId(fallback) {
    const fromAnswers = skuFromPathwaiAnswers();
    if (fromAnswers) return rememberSku(fromAnswers);
    const remembered = rememberedSku();
    if (isFinasterideOralTabletsPriceId(remembered)) return remembered;
    const visit = remapFinasterideOralTabletsId(visitingPriceId());
    if (isFinasterideOralTabletsPriceId(visit)) return visit;
    return resolvePrimaryPriceId(fallback);
  }

  function mergePriceIdParam(search, priceId) {
    const raw = String(search || '').replace(/^\?/, '');
    const id = Number(priceId);
    if (!id) return raw;
    if (/priceId=/i.test(raw)) return raw.replace(/priceId=\d+/i, `priceId=${id}`);
    return raw ? `${raw}&priceId=${id}` : `priceId=${id}`;
  }

  function readBodyPriceId(body, url) {
    if (body == null) return 0;
    if (typeof FormData !== 'undefined' && body instanceof FormData) {
      return Number(body.get('productPriceId') || body.get('ProductPriceId') || 0);
    }
    if (typeof body !== 'string') return 0;
    if (url && /ValidateVisitingId/i.test(url)) {
      try {
        const json = JSON.parse(body);
        return Number(json?.ProductPriceId || json?.productPriceId || 0);
      } catch (e) { /* not json */ }
    }
    const m = body.match(/productPriceId=([^&]*)/i);
    return m ? Number(decodeURIComponent(m[1])) : 0;
  }

  function readBodySlug(body, url) {
    if (body == null) return '';
    if (typeof FormData !== 'undefined' && body instanceof FormData) {
      return String(body.get('slug') || body.get('ProductSlug') || body.get('productSlug') || '');
    }
    if (typeof body !== 'string') return '';
    if (url && /ValidateVisitingId/i.test(url)) {
      try {
        const json = JSON.parse(body);
        return String(json?.ProductSlug || json?.productSlug || json?.slug || '');
      } catch (e) { /* not json */ }
    }
    const m = body.match(/(?:ProductSlug|productSlug|slug)=([^&]*)/i);
    return m ? decodeURIComponent(m[1]) : '';
  }

  function injectFormField(body, key, value) {
    if (value == null || value === '') return body;
    const encoded = encodeURIComponent(String(value));
    if (typeof body === 'string') {
      if (new RegExp(key + '=').test(body)) {
        return body.replace(new RegExp(key + '=[^&]*'), key + '=' + encoded);
      }
      return body + (body ? '&' : '') + key + '=' + encoded;
    }
    if (typeof FormData !== 'undefined' && body instanceof FormData) {
      body.set(key, String(value));
      return body;
    }
    return body;
  }

  /* ─── AUTH ─────────────────────────────────────────────────────────────── */

  async function signup(email, password, phone, opts = {}) {
    _log('CheckEmail');
    await api('PUT', 'auth/CheckEmail', { form: { email } });

    _log('SignUpWithEmail', email);
    const signupRes = await api('POST', 'auth/SignUpWithEmail', { json: { Email: email, Phone: phone } });

    _log('SetVerifyIdentity', signupRes.Id);
    const user = await api('PUT', `auth/SetVerifyIdentity?id=${signupRes.Id}&secureParam=${encodeURIComponent(signupRes.secureParam)}`);
    // Ensure email is on the stored access user — PathwAI payment reads it for customerEmail
    if (user && !user.Email) user.Email = email;
    if (user && !user.UserName) user.UserName = email;
    lsSet(LS.ACCESS_TOKEN, user);
    lsSet(LS.AUTH_PARAMS, { Id: signupRes.Id, secureParam: signupRes.secureParam, Flow: 'Registration', dob: '', email });

    _log('CompleteAccount (set password)', email);
    await api('POST', 'auth/CompleteAccount', {
      json: {
        SecureParam:     signupRes.secureParam,
        FirstName:       opts.firstName || '',
        LastName:        opts.lastName  || '',
        Email:           email,
        Password:        password,
        ConfirmPassword: password,
        Phone:           phone,
        Gender:          opts.gender ?? 0,
      },
    });

    try {
      if (typeof window !== 'undefined' && window.pathwai?.user?.mergeProfile) {
        window.pathwai.user.mergeProfile({
          email,
          firstName: opts.firstName || '',
          lastName: opts.lastName || '',
          phone: phone || '',
        });
      }
    } catch (e) { /* ignore */ }

    persistCustomerEmail(user?.Email || email, { mergeProfile: true });
    _log('Signed up + password set, token stored', { Id: user.Id, Email: user.Email || email });
    return user;
  }

  async function loginWithPassword(email, password, ipAddress) {
    const ip = ipAddress || await fetch('https://ipinfo.io/ip').then(r => r.text()).catch(() => '127.0.0.1');
    _log('Login', email);
