  function isEmail(value) {
    const s = String(value || '').trim();
    return s.includes('@') && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s) ? s : '';
  }

  function emailFromObject(obj) {
    if (!obj || typeof obj !== 'object') return '';
    return isEmail(obj.Email) || isEmail(obj.email) || isEmail(obj.UserName) || isEmail(obj.userName)
      || isEmail(obj.CustomerEmail) || isEmail(obj.customerEmail) || '';
  }

  function persistCustomerEmail(email, opts) {
    const resolved = isEmail(email);
    if (!resolved) return '';
    try { window.strut_customer_email = resolved; } catch (e) { /* ignore */ }
    const user = getAccessUser();
    if (user && typeof user === 'object') {
      if (!isEmail(user.Email)) user.Email = resolved;
      if (!isEmail(user.UserName)) user.UserName = resolved;
      lsSet(LS.ACCESS_TOKEN, user);
    }
    try {
      const params = getAuthParams() || {};
      params.email = resolved;
      lsSet(LS.AUTH_PARAMS, params);
    } catch (e) { /* ignore */ }
    if (opts && opts.mergeProfile && !isPaymentScreen()) {
      try { window.pathwai?.user?.mergeProfile?.({ email: resolved }); } catch (e) { /* ignore */ }
    }
    return resolved;
  }

  function seedPaymentEmail(reason) {
    const email = resolveCustomerEmail();
    if (!email) {
      _log('customerEmail missing — PathwAI payment will fail', reason || '');
      return '';
    }
    persistCustomerEmail(email, { mergeProfile: true });
    try { window.strut_customer_email = email; } catch (e) { /* ignore */ }
    if (!window.__strutFinasterideOralTabletsEmailSeeded) {
      window.__strutFinasterideOralTabletsEmailSeeded = true;
      _log('Seeded PathwAI customerEmail', email, reason || '');
