  function resolveCustomerEmail() {
    const user = getAccessUser();
    let found = emailFromObject(user)
      || emailFromObject(user?.AccessToken)
      || emailFromObject(user?.Customer)
      || emailFromObject(user?.User);
    if (found) return persistCustomerEmail(found);

    try {
      found = emailFromObject(window.pathwai?.user?.getUser?.()?.profile)
        || isEmail(window.pathwai?.user?.getUser?.()?.email);
      if (found) return persistCustomerEmail(found);
    } catch (e) { /* ignore */ }

    try {
      found = isEmail(getAuthParams()?.email);
      if (found) return persistCustomerEmail(found);
    } catch (e) { /* ignore */ }

    try {
      found = isEmail(window.strut_customer_email);
      if (found) return persistCustomerEmail(found);
    } catch (e) { /* ignore */ }

    try {
      const token = getToken();
      if (token) {
        const payload = JSON.parse(atob(token.split('.')[1].replace(/-/g, '+').replace(/_/g, '/')));
        found = isEmail(payload.email) || isEmail(payload.Email) || isEmail(payload.unique_name)
          || isEmail(payload.upn) || isEmail(payload.preferred_username);
        if (found) return persistCustomerEmail(found);
      }
    } catch (e) { /* ignore */ }

    try {
      found = emailFromObject(getVisiting()) || emailFromObject(getOrder()) || emailFromObject(getOrder()?.Cart);
      if (found) return persistCustomerEmail(found);
    } catch (e) { /* ignore */ }

    try {
      const answers = window.pathwai?.flow?.getAnswers?.() || {};
      for (const v of Object.values(answers)) {
        if (typeof v === 'string') found = isEmail(v);
        else if (v && typeof v === 'object') found = emailFromObject(v) || isEmail(v.value) || isEmail(v.answer);
        if (found) return persistCustomerEmail(found);
      }
    } catch (e) { /* ignore */ }

    return '';
  }

