  /* ─── SELFIE / ID PHOTOS (admin + physician Photos tab) ────────────────── */

  const PHOTO_SLOTS = {
    id:     { Id: 1, Name: 'Can you upload ID ?', ShortName: 'ID' },
    selfie: { Id: 2, Name: 'Can you upload the avatar', ShortName: 'Selfie' },
  };

  const photoUploadJobs = [];

  function photoSlotFromHint(hint) {
    const s = String(hint || '').toLowerCase();
    if (!s || /product|catalog|placeholder|logo|price/.test(s)) return null;
    const selfie = /selfie|current[-_\s]?selfie|\bavatar\b/.test(s);
    const id = /photo[-_\s]?id|id[-_\s]?photo|government[-_\s]?id|passport|licen[sc]e|identification|current[-_\s]?government[-_\s]?id/.test(s);
    if (id && !selfie) return PHOTO_SLOTS.id;
    if (selfie && !id) return PHOTO_SLOTS.selfie;
    return null;
  }

  function nodeText(node) {
    return String((node && (node.innerText || node.textContent)) || '').replace(/\s+/g, ' ').trim().slice(0, 900);
  }

  function slotFlags(text) {
    const s = String(text || '').toLowerCase();
    return {
      selfie: /selfie|current[-_\s]?selfie/.test(s),
      id: /photo[-_\s]?id|id[-_\s]?photo|government[-_\s]?id|passport|licen[sc]e|identification/.test(s),
    };
  }

  // Walk from the clicked control. Photo ID and Selfie are sibling cards, so a
  // parent that contains both is split and the branch under the click is used.
  function elementSlot(el) {
    const start = el && el.nodeType === 1 ? el : (el && el.parentElement);
    let node = start;
    while (node && node !== document.body) {
      const flags = slotFlags(nodeText(node));
      if (flags.id && !flags.selfie) return PHOTO_SLOTS.id;
      if (flags.selfie && !flags.id) return PHOTO_SLOTS.selfie;
      if (flags.id && flags.selfie) {
        let branch = start;
        while (branch && branch.parentElement && branch.parentElement !== node) branch = branch.parentElement;
        if (branch && branch !== node) {
          const inner = slotFlags(nodeText(branch));
          if (inner.id && !inner.selfie) return PHOTO_SLOTS.id;
          if (inner.selfie && !inner.id) return PHOTO_SLOTS.selfie;
        }
        return null;
      }
      node = node.parentElement;
    }
    return null;
  }

  function captureControlText(el) {
    let node = el && el.nodeType === 1 ? el : (el && el.parentElement);
    for (let i = 0; node && node !== document.body && i < 5; i++) {
      const text = nodeText(node);
      if (text.length < 120 && /take picture|^upload$|upload a file|upload a selfie|upload one/i.test(text)) return text;
      node = node.parentElement;
    }
    return '';
  }

  function photoStepText() {
    try {
      return String((document.body && document.body.innerText) || '').slice(0, 1800);
    } catch (e) {
      return '';
    }
  }

  function photoStepVisible() {
    return /selfie|upload (a |your )?(photo|picture|id)|government[- ]issued|photo id|take a photo/i.test(photoStepText());
  }

  let armedPhotoSlot = null;
  let armedPhotoAt = 0;

  function labelSlots() {
    const out = [];
    if (!document.querySelectorAll) return out;
    document.querySelectorAll('h1,h2,h3,h4,h5,h6,p,span,div,label,strong').forEach((node) => {
      const text = nodeText(node);
      if (!text || text.length > 48) return;
      const flags = slotFlags(text);
      if (flags.id === flags.selfie) return;
      const rect = node.getBoundingClientRect();
      if (!rect.width && !rect.height) return;
      out.push({ slot: flags.id ? PHOTO_SLOTS.id : PHOTO_SLOTS.selfie, rect });
    });
    return out;
  }

  // The two Take picture buttons often sit in one component, so ancestor text
  // contains both "Photo ID" and "Selfie". Use the heading closest to the click.
  function nearestSlot(el) {
    const fromTree = elementSlot(el);
    if (fromTree) return fromTree;
    if (!el || !el.getBoundingClientRect) return null;
    const rect = el.getBoundingClientRect();
    const y = rect.top + (rect.height / 2);
    const x = rect.left + (rect.width / 2);
    let best = null;
    let bestDist = Infinity;
    labelSlots().forEach((label) => {
      const ly = label.rect.top + (label.rect.height / 2);
      const lx = label.rect.left + (label.rect.width / 2);
      const dist = Math.abs(ly - y) + (Math.abs(lx - x) * 0.25);
      if (dist < bestDist) {
        bestDist = dist;
        best = label.slot;
      }
    });
    return best;
  }

  function armPhotoSlot(el) {
    const slot = nearestSlot(el);
    if (!slot) return null;
    armedPhotoSlot = slot;
    armedPhotoAt = Date.now();
    _log('Armed photo capture', slot.ShortName);
    return slot;
  }

  function takeArmedSlot() {
    if (!armedPhotoSlot || Date.now() - armedPhotoAt > 120000) return null;
    return armedPhotoSlot;
  }

  function slotForFileInput(input) {
    // The camera input is one shared control and often lives in the Selfie
    // card. The Take picture button that opened it owns the file.
    const marked = input && input.getAttribute && input.getAttribute('data-strut-photo-slot');
    if (marked === 'ID') return PHOTO_SLOTS.id;
    if (marked === 'Selfie') return PHOTO_SLOTS.selfie;
    const armed = takeArmedSlot();
    if (armed) return armed;
    return elementSlot(input);
  }

  function stampFileInput(input, slot) {
    if (!input || !slot || input.type !== 'file') return;
    input.setAttribute('data-strut-photo-slot', slot.ShortName);
  }

  function photoSourceKey(slot, raw) {
    const value = String(raw || '');
    const mark = value.length > 80 ? (value.length + ':' + value.slice(-32)) : value;
    return slot.ShortName + ':' + mark;
  }

  function slotFromIdentityKey(key) {
    const compact = String(key || '').toLowerCase().replace(/[^a-z]/g, '');
    if (compact === 'selfiedataurl' || compact === 'selfieurl') return PHOTO_SLOTS.selfie;
    if (compact === 'documentdataurl' || compact === 'documenturl' || compact === 'iddataurl') return PHOTO_SLOTS.id;
    return null;
  }

  function isImageFile(file) {
    const type = String((file && file.type) || '').toLowerCase();
    if (type.indexOf('image/') === 0 && type.indexOf('svg') === -1) return true;
    const name = String((file && file.name) || '').toLowerCase();
    return /\.(jpe?g|png|heic|webp)$/i.test(name) && type.indexOf('text/') !== 0 && type.indexOf('html') === -1 && type.indexOf('json') === -1;
  }

  function looksLikeImageRef(url, name, type) {
    const u = String(url || '');
    const n = String(name || '');
    const t = String(type || '').toLowerCase();
    if (t.indexOf('image/') === 0) return true;
    if (/^data:image\//i.test(u)) return true;
    return /\.(jpe?g|png|heic|webp)(\?|$)/i.test(u) || /\.(jpe?g|png|heic|webp)$/i.test(n);
  }

  function getRememberedPhotos() {
    const stored = lsGet(LS.PHOTOS);
    return Array.isArray(stored) ? stored.filter(p => p && p.NameGUID && p.Id) : [];
  }

  function rememberPhoto(row) {
    if (!row || !row.NameGUID || !row.Id) return getRememberedPhotos();
    const existing = getRememberedPhotos().find(p => Number(p.Id) === Number(row.Id));
    if (existing && existing.locked && !row.locked) return getRememberedPhotos();
    const next = getRememberedPhotos().filter(p => Number(p.Id) !== Number(row.Id));
    next.push(row);
    next.sort((a, b) => Number(a.Id) - Number(b.Id));
    lsSet(LS.PHOTOS, next);
    try { lsDel(LS.PHOTOS_SAVED); } catch (e) { /* ignore */ }
    _log('Remembered order photo', { Id: row.Id, ShortName: row.ShortName, FileName: row.FileName, NameGUID: row.NameGUID });
    return next;
  }

  function photoPayload(photos) {
    return (photos || getRememberedPhotos()).map(p => ({
      Id: p.Id,
      Name: p.Name,
      ShortName: p.ShortName,
      FileName: p.FileName,
      NameGUID: p.NameGUID,
    }));
  }

  function trackPhotoJob(promise) {
    const job = Promise.resolve(promise).finally(() => {
      const i = photoUploadJobs.indexOf(job);
      if (i >= 0) photoUploadJobs.splice(i, 1);
    });
    photoUploadJobs.push(job);
    return job;
  }

  async function uploadMediaFile(file, fileName) {
    const blob = file instanceof Blob ? file : null;
    if (!blob) throw new Error('uploadMediaFile requires a File or Blob');
    const name = String(fileName || file.name || 'photo.jpg');
    const fd = new FormData();
    fd.append('file', blob, name);
    const data = await api('PUT', 'media/UploadFiles', { formData: fd });
    const nameGuid = data && (data.NameGUID || data.nameGuid);
    if (!nameGuid) throw new Error('media/UploadFiles returned no NameGUID');
    return {
      FileName: (data && (data.FileName || data.fileName)) || name,
      NameGUID: String(nameGuid),
    };
  }

  function walkPhotoCandidates(node, hits, path) {
    if (node == null || hits.length > 12) return;
    if (typeof node === 'string') {
      const identitySlot = /^data:image\//i.test(node) ? slotFromIdentityKey(path) : null;
      const slot = identitySlot || photoSlotFromHint(path);
      if (slot && (identitySlot || looksLikeImageRef(node, '', ''))) {
        hits.push({ url: node, hint: path, name: slot.Id === 1 ? 'id.jpg' : 'selfie.jpg', slot });
      }
      return;
    }
    if (Array.isArray(node)) {
      node.forEach((item, i) => walkPhotoCandidates(item, hits, path + '.' + i));
      return;
    }
    if (typeof node !== 'object') return;
    const url = node.url || node.fileUrl || node.publicUrl || node.downloadUrl || node.href || node.src || node.uri || node.dataUrl || node.preview || '';
    const name = node.name || node.fileName || node.filename || node.originalName || '';
    const type = node.type || node.mimeType || node.contentType || '';
    const label = node.label || node.title || node.slot || node.kind || node.role || node.key || node.caption || '';
    const hint = [path, name, type, label].filter(Boolean).join(' ');
    const slot = photoSlotFromHint(hint);
    if (url && slot && looksLikeImageRef(url, name, type)) {
      hits.push({ url: String(url), hint, name: String(name || (slot.ShortName + '.jpg')), slot });
      return;
    }
    Object.keys(node).forEach((k) => {
      walkPhotoCandidates(node[k], hits, path ? path + '.' + k : k);
    });
  }

  function collectPathwaiPhotoCandidates() {
    const hits = [];
    const roots = [];
    try {
      const pw = window.pathwai || {};
      roots.push(pw.answers, pw.flow && pw.flow.answers, pw.variables, pw.flow && pw.flow.variables, pw.state);
      if (pw.flow && pw.flow.getAnswers) roots.push(pw.flow.getAnswers());
      if (pw.user) roots.push(pw.user.answers);
    } catch (e) { /* ignore */ }
    roots.forEach((root) => walkPhotoCandidates(root, hits, ''));
    const seen = new Set();
    return hits.filter((item) => {
      if (!item || !item.url || seen.has(item.url)) return false;
      seen.add(item.url);
      return true;
    });
  }

  async function uploadPhotoBlob(blob, slot, fileName, source) {
    if (!slot || !blob) return null;
    const existing = getRememberedPhotos().find(p => p.source && source && p.source === source);
    if (existing) return existing;
    const uploaded = await uploadMediaFile(blob, fileName);
    return rememberPhoto({
      Id: slot.Id,
      Name: slot.Name,
      ShortName: slot.ShortName,
      FileName: uploaded.FileName,
      NameGUID: uploaded.NameGUID,
      source: source || uploaded.NameGUID,
      locked: false,
    });
  }

  function canUploadCapture(file) {
    if (!file || !file.size) return false;
    if (isImageFile(file)) return true;
    const type = String(file.type || '').toLowerCase();
    return !type || type === 'application/octet-stream';
  }

  async function uploadPhotoFile(file, slot) {
    if (!file || !slot || !canUploadCapture(file)) return null;
    const safeName = /\.(jpe?g|png|heic|webp)$/i.test(file.name || '') ? file.name : (slot.ShortName.toLowerCase() + '.jpg');
    const source = [slot.ShortName, file.name, file.size, file.lastModified].join(':');
    const uploaded = await uploadMediaFile(file, safeName);
    return rememberPhoto({
      Id: slot.Id,
      Name: slot.Name,
      ShortName: slot.ShortName,
      FileName: uploaded.FileName,
      NameGUID: uploaded.NameGUID,
      source: source,
      locked: true,
    });
  }

  async function uploadPathwaiPhoto(item) {
    if (!item || !item.url || !item.slot) return null;
    if (getRememberedPhotos().some(p => p.source === item.url)) return null;
    let blob;
    if (/^data:/i.test(item.url)) {
      const res = await fetch(item.url);
      blob = await res.blob();
    } else if (/^blob:/i.test(item.url)) {
      const res = await fetch(item.url);
      blob = await res.blob();
    } else {
      const res = await fetch(item.url, { mode: 'cors', credentials: 'omit' });
      if (!res.ok) {
        _log('Photo fetch failed — use the file upload on the selfie step', item.url, res.status);
        return null;
      }
      blob = await res.blob();
    }
    const type = String(blob.type || '').toLowerCase();
    if (type && type.indexOf('image/') !== 0) return null;
    const name = (item.slot.ShortName.toLowerCase() + '.jpg');
    const file = blob instanceof File ? blob : new File([blob], name, { type: type || 'image/jpeg' });
    if (!isImageFile(file)) return null;
    return uploadPhotoBlob(file, item.slot, name, photoSourceKey(item.slot, item.url));
  }

  function collectIdentityAnswerPhotos(node, hits, depth) {
    if (node == null || depth > 8 || hits.length >= 4) return;
    if (Array.isArray(node)) {
      node.forEach((item) => collectIdentityAnswerPhotos(item, hits, depth + 1));
      return;
    }
    if (typeof node !== 'object') return;
    Object.keys(node).forEach((key) => {
      const value = node[key];
      const slot = slotFromIdentityKey(key);
      if (slot && typeof value === 'string' && /^data:image\//i.test(value)) {
        hits.push({ url: value, slot, name: slot.Id === 1 ? 'id.jpg' : 'selfie.jpg' });
        return;
      }
      if (value && typeof value === 'object') collectIdentityAnswerPhotos(value, hits, depth + 1);
    });
  }

  function collectIdentityCardPhotos() {
    const hits = [];
    if (!document.querySelectorAll) return hits;
    document.querySelectorAll('.psi-slot').forEach((slotEl) => {
      const title = nodeText(slotEl.querySelector('.psi-slot-title'));
      const flags = slotFlags(title);
      let slot = null;
      if (flags.id && !flags.selfie) slot = PHOTO_SLOTS.id;
      else if (flags.selfie && !flags.id) slot = PHOTO_SLOTS.selfie;
      if (!slot) return;
      const frame = slotEl.querySelector('.psi-frame');
      if (!frame) return;
      const bg = String((frame.style && frame.style.backgroundImage) || window.getComputedStyle(frame).backgroundImage || '');
      const match = bg.match(/url\((['"]?)(data:image\/[^"')]+)\1\)/i);
      if (!match) return;
      hits.push({ url: match[2], slot, name: slot.Id === 1 ? 'id.jpg' : 'selfie.jpg' });
    });
    return hits;
  }

  function collectIdentityOutputs() {
    const hits = collectIdentityCardPhotos();
    try {
      const pw = window.pathwai || {};
      const roots = [pw.answers, pw.flow && pw.flow.answers, pw.variables, pw.flow && pw.flow.variables, pw.state, pw.user && pw.user.answers];
      if (pw.flow && pw.flow.getAnswers) roots.push(pw.flow.getAnswers());
      roots.forEach((root) => collectIdentityAnswerPhotos(root, hits, 0));
    } catch (e) { /* ignore */ }
    return hits;
  }

  function collectCardPhotoPreviews() {
    const hits = [];
    if (!document || !document.querySelectorAll || !photoStepVisible()) return hits;
    document.querySelectorAll('img').forEach((img) => {
      const src = String(img.currentSrc || img.src || '');
      if (!src || /logo|icon|placeholder|sprite|data:image\/svg/i.test(src)) return;
      if (!img.complete || !img.naturalWidth || img.naturalWidth < 48) return;
      const slot = nearestSlot(img);
      if (!slot) return;
      hits.push({ url: src, slot, name: slot.ShortName.toLowerCase() + '.jpg' });
    });
    return hits;
  }

  async function scrapeVisiblePhotoCards() {
    const identity = collectIdentityOutputs();
    for (let i = 0; i < identity.length; i++) {
      try {
        await uploadPathwaiPhoto(identity[i]);
      } catch (e) {
        _log('Identity photo upload failed', identity[i] && identity[i].slot && identity[i].slot.ShortName, e && e.message);
      }
    }
    const previews = collectCardPhotoPreviews();
    const canvases = document.querySelectorAll ? document.querySelectorAll('canvas') : [];
    for (let i = 0; i < canvases.length; i++) {
      const canvas = canvases[i];
      const slot = nearestSlot(canvas);
      if (!slot || canvas.width < 48 || canvas.height < 48) continue;
      try {
        const blob = await new Promise((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.92));
        if (blob) {
          await uploadPhotoBlob(
            blob,
            slot,
            slot.ShortName.toLowerCase() + '.jpg',
            photoSourceKey(slot, canvas.width + 'x' + canvas.height + ':' + blob.size)
          );
        }
      } catch (e) {
        _log('Photo canvas capture failed', e && e.message);
      }
    }
    for (let i = 0; i < previews.length; i++) {
      try {
        await uploadPathwaiPhoto(previews[i]);
      } catch (e) {
        _log('Photo card preview upload failed', e && e.message);
      }
    }
    return getRememberedPhotos();
  }

  async function ensureOrderPhotosUploaded() {
    if (photoUploadJobs.length) {
      await Promise.all(photoUploadJobs.map(job => job.catch(() => null)));
    }
    try { await scrapeVisiblePhotoCards(); } catch (e) {
      _log('Photo card scrape failed', e && e.message);
    }
    const candidates = collectPathwaiPhotoCandidates();
    for (let i = 0; i < candidates.length; i++) {
      try {
        await uploadPathwaiPhoto(candidates[i]);
      } catch (e) {
        _log('PathwAI photo upload failed', e && e.message);
      }
    }
    return getRememberedPhotos();
  }

  async function saveOrderPhotos() {
    const photos = await ensureOrderPhotosUploaded();
    const payloadPhotos = photoPayload(photos);
    if (!payloadPhotos.length) {
      _log('SavePhotoUpload skipped — no selfie or ID photo captured');
      return null;
    }
    if (!getOrderId() && getVisitingId()) {
      try { await getCurrentVisiting(); } catch (e) {
        _log('GetCurrentVisiting before SavePhotoUpload failed', e && e.message);
      }
    }
    const oid = getOrderId();
    const vid = getVisitingId();
    if (!oid || !vid) {
      _log('SavePhotoUpload waiting for visiting/order', { photos: payloadPhotos.length });
      return null;
    }
    const marker = String(oid) + ':' + payloadPhotos.map(p => p.Id + '=' + p.NameGUID).join(',');
    if (lsGet(LS.PHOTOS_SAVED) === marker) return payloadPhotos;
    _log('SavePhotoUpload', { orderId: oid, visitingId: vid, photos: payloadPhotos });
    await api('POST', `checkout/SavePhotoUpload?orderId=${oid}&visitingId=${encodeURIComponent(vid)}`, {
      json: { photos: payloadPhotos },
    });
    lsSet(LS.PHOTOS_SAVED, marker);
    return payloadPhotos;
  }

  function installPhotoCapture() {
    if (window.__strutFinasterideOralTabletsPhotoCapture === 'v3') return;
    window.__strutFinasterideOralTabletsPhotoCapture = 'v3';

    if (!HTMLInputElement.prototype.__strutPhotoClick) {
      const origInputClick = HTMLInputElement.prototype.click;
      HTMLInputElement.prototype.click = function () {
        if (this && this.type === 'file') stampFileInput(this, takeArmedSlot());
        return origInputClick.apply(this, arguments);
      };
      HTMLInputElement.prototype.__strutPhotoClick = true;
    }

    document.addEventListener('click', function (e) {
      const clicked = captureControlText(e.target) || (/capture photo/i.test(nodeText(e.target).slice(0, 80)) ? 'Capture photo' : '');
      if (!clicked) return;
      const slot = armPhotoSlot(e.target);
      if (slot) {
        document.querySelectorAll('input[type="file"]').forEach(function (input) {
          stampFileInput(input, slot);
        });
      }
      [400, 1200, 2500].forEach((ms) => {
        setTimeout(() => {
          if (!photoStepVisible()) return;
          trackPhotoJob(scrapeVisiblePhotoCards());
        }, ms);
      });
    }, true);

    document.addEventListener('change', function (e) {
      const input = e.target;
      if (!input || input.type !== 'file' || !input.files || !input.files.length) return;
      const slot = slotForFileInput(input);
      if (!slot) {
        _log('Photo file ignored — click Take picture on Photo ID or Selfie first');
        return;
      }
      _log('Photo file captured for', slot.ShortName, input.files[0] && input.files[0].name);
      const files = Array.from(input.files);
      trackPhotoJob((async () => {
        for (let i = 0; i < files.length; i++) {
          try {
            await uploadPhotoFile(files[i], slot);
          } catch (err) {
            _log('Selfie/ID file upload failed', err && err.message);
          }
        }
      })());
    }, true);

    window.setInterval(function () {
      if (!photoStepVisible()) return;
      if (getRememberedPhotos().length >= 2) return;
      trackPhotoJob(scrapeVisiblePhotoCards());
    }, 2000);
  }

  /* ─── FINISH ORDER ─────────────────────────────────────────────────────── */

  function _buildLineItems(order) {
    // Finasteride Oral Tablets is a single supply SKU. Do not forward leftover SuperStrut /
    // testosterone / BHRT / lab bundle lines from a prior visiting.
    const selected = (order?.Cart?.BundleProducts || []).filter(o => o.Selected);
    const otc = [];
    const rx = selected
      .filter(o => o.OtcOrRxProductPortalItemId > 0)
      .filter(o => isFinasterideOralTabletsPriceId(o.OtcOrRxProductPortalItemId || o.ProductPriceId))
      .map(el => ({
        Id: el.Id,
        ProductPriceId: el.OtcOrRxProductPortalItemId,
        Answers: el.Answers,
        ProductPriceChangeId: el.ProductPriceChangeId,
        ExtraProductIds: el.ExtraProductIds,
      }));
    if (selected.length && !rx.length) {
      _log('Dropped foreign cart add-ons (not Finasteride Oral Tablets)', selected.map(o => ({
        name: o.ProductName || o.Name,
        priceId: o.OtcOrRxProductPortalItemId,
      })));
    }
    return {
      otcJson:  otc.length ? JSON.stringify(otc) : '',
      rxJson:   rx.length  ? JSON.stringify(rx)  : '',
      quantity: order?.Cart?.Quantity ?? 1,
    };
  }

  async function finishOrderV2(profiles, opts = {}) {
    if (!profiles?.customerProfileId || !profiles?.paymentProfileId) {
      throw new Error(
        'finishOrderV2 requires { customerProfileId, paymentProfileId }\n' +
        'Get these from your Authorize.net Accept.js tokenization backend.'
      );
    }
    const order = getOrder();
    const visit = getVisiting();
    const vid   = opts.visitingId || getVisitingId();
    const oid   = opts.orderId    || getOrderId();
    const { otcJson, rxJson, quantity } = _buildLineItems(order);
    const primary = resolveCheckoutPriceId(opts.productPriceId || visit?.ProductPriceId);
    const urlParam = mergePriceIdParam(
      opts.urlParam || (window.location && window.location.search.substring(1)),
      primary
    );

    _log('FinishOrderV2', { oid, vid, productPriceId: primary, ...profiles });
    window.__strutFinasterideOralTabletsOwnFinish = true;
    try {
      try { await saveOrderPhotos(); } catch (e) {
        _log('SavePhotoUpload before FinishOrderV2 failed', e && e.message);
      }
      const result = await api('PUT', 'checkout/FinishOrderV2', {
        form: {
          visitingId:                vid,
          orderId:                   oid,
          customerProfileId:         profiles.customerProfileId,
          paymentProfileId:          profiles.paymentProfileId,
          quantity,
          otcJson,
          rxJson,
          productPriceId:            primary,
          pageWarningSelectOption:   opts.pageWarningSelectOption ?? order?.PageWarningSelectOption ?? '',
          urlParam,
        }
      });
      markOrderSubmitted(result);
      return result;
    } finally {
      window.__strutFinasterideOralTabletsOwnFinish = false;
    }
  }

  async function finishOrderLegacy(opts = {}) {
    const order = getOrder();
    const vid   = opts.visitingId || getVisitingId();
    const oid   = opts.orderId    || getOrderId();
    const { otcJson, rxJson, quantity } = _buildLineItems(order);
    _log('FinishOrder (legacy)', { oid, vid });
    try { await saveOrderPhotos(); } catch (e) {
      _log('SavePhotoUpload before FinishOrder failed', e && e.message);
    }
    return api('PUT', 'checkout/FinishOrder', {
      form: {
        visitingId:              vid,
        orderId:                 oid,
        quantity,
        otcJson,
        rxJson,
        pageWarningSelectOption: opts.pageWarningSelectOption ?? order?.PageWarningSelectOption ?? '',
        urlParam:                mergePriceIdParam(window.location && window.location.search.substring(1), resolveCheckoutPriceId()),
      }
    });
  }

  async function getOrderStatus(orderId) {
    const oid = orderId || getOrderId();
    return api('GET', `checkout/GetStatusOrder?orderId=${oid}`);
  }

  /* ─── PIPELINE ─────────────────────────────────────────────────────────── */

  async function runFlow(profiles, opts = {}) {
    _log('── runFlow start ──');

    if (!opts.skipDosage) {
      const pid = resolveCheckoutPriceId(opts.productPriceId) || getProductPriceId();
      _log('Step: SaveDosage', pid);
      await saveDosage(pid);
    }

    if (!opts.skipAnswers && opts.answers?.length) {
      _log('Step: SaveQuestionAnswer', opts.answers.length);
      await saveAnswers(opts.answers).catch(e => _log('answers skipped:', e.message));
    }

    _log('Step: refresh GetCurrentVisiting');
    const order = await getCurrentVisiting();

    if (!opts.skipShipping) {
      _log('Step: getAddressSeed');
      const seed = await getAddressSeed();
      _log('Step: createAddress');
      await createAddress(opts.address || {
        Address1:        seed?.Address1 || '123 Main St',
        Address2:        '',
        StateProvinceId: seed?.StateProvinceId || 5,
        City:            seed?.City     || 'San Francisco',
        ZipPostalCode:   seed?.ZipPostalCode || '94102',
      });
      const addrs = await getAddresses();
      const addrId = addrs[0]?.Id;
      if (!addrId) throw new Error('No address found after create');
      _log('Step: SaveShippingAddress', addrId);
      await saveShipping(addrId);
    }

    _log('Step: FinishOrderV2');
    const result = await finishOrderV2(profiles, opts);
    _log('── runFlow complete ──', result);
    return result;
  }

