    const info = {
      env:        ENV,
      token:      token ? `${token.slice(0, 20)}…` : null,
      tokenExpiry: null,
      userId:     user?.Id,
      email:      resolveCustomerEmail() || user?.Email || user?.UserName,
      flow:       params?.Flow,
      dob:        params?.dob || null,
      visitingId: visit?.VisitingId,
      productSlug:visit?.ProductSlug,
