      productName:    visit?.ProductName,
      orderId:    order?.OrderId,
      customerId: order?.CustomerId,
      authNet:    rememberedAuthNetProfiles(),
      orderSubmitted: alreadySubmittedOrder(),
      photos: photoPayload().map(p => ({ ShortName: p.ShortName, FileName: p.FileName, NameGUID: p.NameGUID })),
      cart: order?.Cart ? {
