  /* ─── HOOK: inject productPriceId on PathwAI's own FinishOrderV2 ──────── */

  function rewriteVisitingPriceInBody(url, method, body) {
    if (/\/Visiting\/ValidateVisitingId/i.test(url) && /^post$/i.test(method) && typeof body === 'string') {
      try {
        const json = JSON.parse(body);
        const incomingSlug = normalizeSlug(json.ProductSlug || json.productSlug || json.slug) || THIS_SLUG;
        let price = Number(json.ProductPriceId || json.productPriceId || 0);
        price = remapFinasterideOralTabletsId(price);
        if (!priceBelongsToThisFlow(price)) {
          price = resolvePrimaryPriceId(0) || 0;
        } else {
          price = resolvePrimaryPriceId(price) || price;
        }
        json.ProductSlug = THIS_SLUG;
        json.ProductPriceId = price;
        if (discardStaleSessionForIncoming(THIS_SLUG, price) || !getVisiting()?.VisitingId) {
          json.VisitingId = null;
        }
        if (price) rememberSku(price);
        _log('ValidateVisitingId sanitized', { fromSlug: incomingSlug, to: json });
        return JSON.stringify(json);
      } catch (e) { /* not json */ }
    }

    if (/\/Visiting\/GetCurrentVisiting/i.test(url) && /^put$/i.test(method)) {
      const bodyId = readBodyPriceId(body, url);
      const bodySlug = normalizeSlug(readBodySlug(body, url));
      let primary = resolveCheckoutPriceId(bodyId);
      if (!priceBelongsToThisFlow(primary)) primary = 0;
      let next = body;
      if (bodySlug && !isThisSlug(bodySlug)) {
